// Meteor Dodge game
// Assumes a <canvas id="game"></canvas> in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // Resize to fill the container or window.
  const resize = () => {
    canvas.width = canvas.clientWidth || window.innerWidth;
    canvas.height = canvas.clientHeight || window.innerHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // Ship definition
  const ship = {
    w: 40,
    h: 20,
    x: canvas.width / 2,
    y: canvas.height - 30,
    speed: 7,
    color: '#0f0',
  };

  // Input handling – mouse moves ship horizontally, click fires.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    ship.x = e.clientX - rect.left;
    // Clamp within canvas
    ship.x = Math.max(ship.w / 2, Math.min(canvas.width - ship.w / 2, ship.x));
  });
  const lasers = [];
  const fireLaser = () => {
    lasers.push({ x: ship.x, y: ship.y, w: 2, h: 10, speed: 10, color: '#ff0' });
  };
  canvas.addEventListener('mousedown', fireLaser);
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') fireLaser();
  });

  // Meteors
  const meteors = [];
  let meteorSpawnTimer = 0;
  let speedMultiplier = 1;
  let lastTime = 0;
  let gameOver = false;

  const spawnMeteor = () => {
    const size = 20 + Math.random() * 30;
    meteors.push({
      x: Math.random() * (canvas.width - size),
      y: -size,
      w: size,
      h: size,
      speed: 1.5 + Math.random() * 1.5,
      color: '#f44',
    });
  };

  const checkCollision = (a, b) => {
    return (
      a.x < b.x + b.w &&
      a.x + a.w > b.x &&
      a.y < b.y + b.h &&
      a.y + a.h > b.y
    );
  };

  const update = (timestamp) => {
    if (gameOver) return;
    const delta = timestamp - lastTime;
    lastTime = timestamp;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update ship (already positioned by mouse)
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x - ship.w / 2, ship.y - ship.h / 2, ship.w, ship.h);

    // Update lasers
    ctx.fillStyle = '#ff0';
    for (let i = lasers.length - 1; i >= 0; i--) {
      const l = lasers[i];
      l.y -= l.speed;
      if (l.y + l.h < 0) {
        lasers.splice(i, 1);
        continue;
      }
      ctx.fillRect(l.x - l.w / 2, l.y - l.h / 2, l.w, l.h);
    }

    // Spawn meteors
    meteorSpawnTimer += delta;
    if (meteorSpawnTimer > 1000) {
      spawnMeteor();
      meteorSpawnTimer = 0;
    }

    // Increase difficulty over time
    speedMultiplier += delta * 0.00002; // subtle acceleration

    // Update meteors
    ctx.fillStyle = '#f44';
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.y += m.speed * speedMultiplier;
      ctx.fillRect(m.x, m.y, m.w, m.h);

      // Collision with ship
      if (checkCollision(m, { x: ship.x - ship.w / 2, y: ship.y - ship.h / 2, w: ship.w, h: ship.h })) {
        gameOver = true;
      }
      // Meteor reaches bottom
      if (m.y + m.h >= canvas.height) {
        gameOver = true;
      }
      // Collision with lasers
      for (let j = lasers.length - 1; j >= 0; j--) {
        const l = lasers[j];
        if (checkCollision(m, { x: l.x - l.w / 2, y: l.y - l.h / 2, w: l.w, h: l.h })) {
          // remove both
          meteors.splice(i, 1);
          lasers.splice(j, 1);
          break;
        }
      }
    }

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      return;
    }

    requestAnimationFrame(update);
  };

  requestAnimationFrame(update);
})();
